def data(g):
    cells=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v not in (0,9)]
    anchor=next((r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==9)
    r0=min(r for r,c in cells);r1=max(r for r,c in cells);c0=min(c for r,c in cells);c1=max(c for r,c in cells)
    ar,ac=anchor
    direction=(0,1) if ac<c0 else (0,-1) if ac>c1 else (1,0) if ar<r0 else (-1,0)
    kmax=len(g[0])-1-c1 if direction==(0,1) else c0 if direction==(0,-1) else len(g)-1-r1 if direction==(1,0) else r0
    color=g[cells[0][0]][cells[0][1]]
    return cells,anchor,direction,kmax,color

def exact_sweep_mirror(g):
    cells,anchor,(dr,dc),kmax,color=data(g);out=[row[:] for row in g]
    for k in range(1,kmax+1):
        for r,c in cells:out[r+dr*k][c+dc*k]=color
    return out

def scanline_envelope(g):
    cells,anchor,(dr,dc),kmax,color=data(g);out=[row[:] for row in g]
    if dc:
        for r in sorted({r for r,c in cells}):
            cols=[c for rr,c in cells if rr==r]
            low=min(cols)+min(0,dc*kmax);high=max(cols)+max(0,dc*kmax)
            for c in range(low,high+1):out[r][c]=color
    else:
        for c in sorted({c for r,c in cells}):
