            low=min(rows)+min(0,dr*kmax);high=max(rows)+max(0,dr*kmax)
            for r in range(low,high+1):out[r][c]=color
    return out

def independent_rays(g):
    cells,anchor,(dr,dc),kmax,color=data(g);out=[row[:] for row in g]
    for r,c in cells:
        while 0<=r<len(g) and 0<=c<len(g[0]):
            out[r][c]=color;r+=dr;c+=dc
    return out

def always_right(g):
    cells,anchor,direction,kmax,color=data(g);out=[row[:] for row in g]
    for r in sorted({r for r,c in cells}):
